package thaumcraft.mirrors;
import java.util.*;
import com.mojang.serialization.*;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.*;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.capabilities.*;
import net.minecraftforge.common.util.LazyOptional;
import net.minecraftforge.items.*;
import thaumcraft.devices.AuraDeviceEntity;
import thaumcraft.essentia.EssentiaTransport;
import thaumcraft.alchemy.AlchemyMachine;
public final class MirrorEntity extends AuraDeviceEntity implements EssentiaTransport {
 public record State(int version,String identity,Optional<MirrorAddress> link,int instability,List<ItemStack> queue){}
 public static final Codec<State> CODEC=RecordCodecBuilder.<State>create(i->i.group(Codec.intRange(1,1).fieldOf("version").forGetter(State::version),MirrorAddress.ID.fieldOf("identity").forGetter(State::identity),MirrorAddress.CODEC.optionalFieldOf("link").forGetter(State::link),Codec.intRange(0,1000000).fieldOf("instability").forGetter(State::instability),ItemStack.OPTIONAL_CODEC.listOf(27,27).fieldOf("queue").forGetter(State::queue)).apply(i,State::new)).validate(s->s.queue().stream().allMatch(stack->stack.isEmpty()||stack.getCount()<=stack.getMaxStackSize())?DataResult.success(s):DataResult.error(()->"Invalid mirror queue"));
 private String identity=UUID.randomUUID().toString();private MirrorAddress link;private int instability,ticks;private final List<ItemStack> queue=new ArrayList<>(Collections.nCopies(27,ItemStack.EMPTY));private Tag unsupported;
 private final IItemHandler input=new IItemHandler(){public int getSlots(){return 1;}public ItemStack getStackInSlot(int slot){return ItemStack.EMPTY;}public int getSlotLimit(int slot){return 64;}public boolean isItemValid(int slot,ItemStack stack){return slot==0&&!essence()&&peer()!=null;}public ItemStack extractItem(int slot,int amount,boolean simulate){return ItemStack.EMPTY;}public ItemStack insertItem(int slot,ItemStack stack,boolean simulate){var target=slot==0&&!essence()?peer():null;if(target==null)return stack;var rest=target.accept(stack,simulate);if(!simulate&&rest.getCount()!=stack.getCount())addInstability(stack.getCount()-rest.getCount());return rest;}};
 private LazyOptional<IItemHandler> capability=LazyOptional.of(()->input);
 public MirrorEntity(BlockPos p,BlockState s){super(MirrorContent.TYPE.get(),p,s);}
 public boolean supported(){return unsupported==null;}public boolean essence(){return ((MirrorBlock)getBlockState().getBlock()).essence;}public Direction facing(){return getBlockState().getValue(MirrorBlock.FACING);}public int instability(){return instability;}public MirrorAddress link(){return link;}public int queued(){return queue.stream().mapToInt(ItemStack::getCount).sum();}
 public MirrorAddress address(){return new MirrorAddress(GlobalPos.of(level.dimension(),worldPosition),identity);}
 public static MirrorEntity resolve(ServerLevel source,MirrorAddress address){if(address==null)return null;var world=source.getServer().getLevel(address.location().dimension());var p=address.location().pos();return world!=null&&world.hasChunkAt(p)&&world.getBlockEntity(p) instanceof MirrorEntity m&&!m.isRemoved()&&m.supported()&&m.identity.equals(address.identity())?m:null;}
 public static boolean loaded(ServerLevel source,MirrorAddress address){var world=source.getServer().getLevel(address.location().dimension());return world!=null&&world.hasChunkAt(address.location().pos());}
 public MirrorEntity peer(){if(isRemoved()||!(level instanceof ServerLevel l)||!supported()||link==null)return null;var other=resolve(l,link);return other!=null&&other!=this&&other.essence()==essence()&&address().equals(other.link)?other:null;}
 public boolean available(){if(isRemoved()||!(level instanceof ServerLevel l)||!supported())return false;return link==null||loaded(l,link)&&resolve(l,link)==null;}
 public void remember(MirrorAddress destination){if(supported()&&!destination.location().equals(address().location())){link=destination;sync();}}
 public boolean bind(MirrorAddress destination){if(isRemoved()||!(level instanceof ServerLevel l)||!supported()||destination==null||destination.location().equals(address().location()))return false;var other=resolve(l,destination);if(other==null||other.essence()!=essence()||!other.available()&&!address().equals(other.link))return false;if(link!=null&&!link.equals(destination)&&peer()!=null)return false;link=destination;other.link=address();sync();other.sync();return true;}
 public ItemStack accept(ItemStack offered,boolean simulate){if(isRemoved()||!(level instanceof ServerLevel)||!supported()||essence()||offered.isEmpty())return offered;var rest=offered.copy();for(int pass=0;pass<2;pass++)for(int i=0;i<27&&!rest.isEmpty();i++){var old=queue.get(i);if(pass==0?old.isEmpty()||!ItemStack.isSameItemSameComponents(old,rest):!old.isEmpty())continue;int n=Math.min(rest.getCount(),rest.getMaxStackSize()-old.getCount());if(n<=0)continue;if(!simulate){if(old.isEmpty())queue.set(i,rest.copyWithCount(n));else old.grow(n);}rest.shrink(n);}if(!simulate&&rest.getCount()!=offered.getCount())setChanged();return rest;}
 public boolean transport(ItemEntity entity){if(isRemoved()||!(level instanceof ServerLevel l)||essence()||!supported()||!entity.isAlive()||entity.level()!=level||!entity.getBoundingBox().intersects(getBlockState().getShape(level,worldPosition).bounds().move(worldPosition).inflate(.05)))return false;if(entity.getPersistentData().getStringOr("tc_mirror_exit","").equals(identity))return false;long until=entity.getPersistentData().getLongOr("tc_mirror_until",0);if(until>l.getGameTime()&&until<=l.getGameTime()+20)return false;var rest=input.insertItem(0,entity.getItem(),false);if(rest.getCount()==entity.getItem().getCount())return false;if(rest.isEmpty())entity.discard();else entity.setItem(rest);return true;}
 public boolean ejectOne(){if(isRemoved()||!(level instanceof ServerLevel l)||!supported()||essence())return false;for(int i=0;i<27;i++)if(!queue.get(i).isEmpty()){var out=queue.get(i).copyWithCount(1);var face=facing();var center=Vec3.atCenterOf(worldPosition).add(Vec3.atLowerCornerOf(face.getUnitVec3i()).scale(-.25));var entity=new ItemEntity(l,center.x,center.y,center.z,out);entity.setDeltaMovement(face.getStepX()*.15,face.getStepY()*.15,face.getStepZ()*.15);entity.getPersistentData().putLong("tc_mirror_until",l.getGameTime()+20);entity.getPersistentData().putString("tc_mirror_exit",identity);if(!l.addFreshEntity(entity))return false;queue.get(i).shrink(1);addInstability(1);particles();return true;}return false;}
 private void particles(){if(level instanceof ServerLevel l)l.sendParticles(net.minecraft.core.particles.ParticleTypes.PORTAL,worldPosition.getX()+.5,worldPosition.getY()+.5,worldPosition.getZ()+.5,4,.25,.25,.25,.01);}
 public void addInstability(int amount){instability=Math.clamp((long)instability+amount,0,1000000);setChanged();}
 public void serverTick(){if(isRemoved()||!(level instanceof ServerLevel l)||!supported())return;ticks++;if((ticks==1||ticks%40==0)&&link!=null&&peer()==null)bind(link);if(essence()&&ticks%5==0){for(var side:Direction.values())if(thaumcraft.essentia.EssentiaNetwork.pull(l,worldPosition,this,side))break;}if(!essence()){for(var entity:l.getEntitiesOfClass(ItemEntity.class,getBlockState().getShape(level,worldPosition).bounds().move(worldPosition).inflate(.05)).stream().limit(64).toList())transport(entity);if(ticks>20)ejectOne();}if(instability>MirrorRules.threshold(essence())){thaumcraft.aura.AuraManager.addFlux(l,worldPosition,1);instability-=MirrorRules.threshold(essence());setChanged();}if(ticks%100==0&&instability>0){instability--;setChanged();}if(ticks%10==0){boolean active=peer()!=null||queued()>0;if(getBlockState().getValue(MirrorBlock.ACTIVE)!=active)l.setBlockAndUpdate(worldPosition,getBlockState().setValue(MirrorBlock.ACTIVE,active));}}
 public ItemStack droppedItem(){var out=new ItemStack(getBlockState().getBlock());out.set(DataComponents.BLOCK_ENTITY_DATA,net.minecraft.world.item.component.TypedEntityData.of(MirrorContent.TYPE.get(),dropTag()));if(link!=null)out.set(MirrorContent.LINK.get(),link);return out;}
 private CompoundTag dropTag(){var tag=saveWithFullMetadata(level.registryAccess());if(supported())tag.put("mirror",CODEC.encodeStart(level.registryAccess().createSerializationContext(NbtOps.INSTANCE),new State(1,identity,Optional.ofNullable(link),instability,Collections.nCopies(27,ItemStack.EMPTY))).getOrThrow());return tag;}
 public void preRemoveSideEffects(BlockPos pos,BlockState state){super.preRemoveSideEffects(pos,state);if(level instanceof ServerLevel&&supported()){var other=peer();if(other!=null){other.link=null;other.sync();}for(int i=0;i<27;i++){var stack=queue.get(i);queue.set(i,ItemStack.EMPTY);if(!stack.isEmpty())net.minecraft.world.level.block.Block.popResource(level,pos,stack);}}}
 protected void saveAdditional(ValueOutput out){super.saveAdditional(out);if(unsupported!=null)out.store("mirror",Codec.PASSTHROUGH,new Dynamic<>(NbtOps.INSTANCE,unsupported));else out.store("mirror",CODEC,new State(1,identity,Optional.ofNullable(link),instability,queue));}
 protected void loadAdditional(ValueInput in){super.loadAdditional(in);unsupported=null;link=null;instability=0;for(int i=0;i<27;i++)queue.set(i,ItemStack.EMPTY);var raw=in.read("mirror",Codec.PASSTHROUGH);if(raw.isPresent()){var parsed=CODEC.parse(raw.get()).result();if(parsed.isPresent()){var s=parsed.get();identity=s.identity();link=s.link().orElse(null);instability=s.instability();for(int i=0;i<27;i++)queue.set(i,s.queue().get(i));}else unsupported=raw.get().convert(NbtOps.INSTANCE).getValue().copy();}}
 public <T> LazyOptional<T> getCapability(Capability<T> cap,Direction side){return !isRemoved()&&!essence()&&cap==ForgeCapabilities.ITEM_HANDLER?capability.cast():super.getCapability(cap,side);}public void invalidateCaps(){super.invalidateCaps();capability.invalidate();}public void reviveCaps(){super.reviveCaps();capability=LazyOptional.of(()->input);}
 private List<AlchemyMachine> jars(){var other=peer();if(other==null||!essence())return List.of();var result=new ArrayList<AlchemyMachine>();var l=(ServerLevel)other.level;var origin=other.worldPosition;for(int x=(origin.getX()-8)>>4;x<=(origin.getX()+8)>>4;x++)for(int z=(origin.getZ()-8)>>4;z<=(origin.getZ()+8)>>4;z++){var chunk=l.getChunkSource().getChunkNow(x,z);if(chunk!=null)for(var be:chunk.getBlockEntities().values())if(be instanceof AlchemyMachine jar&&jar.jar()&&!jar.braced()&&jar.supported()&&MirrorRules.inFront(origin,jar.getBlockPos(),other.facing()))result.add(jar);}result.sort(Comparator.comparingDouble(jar->jar.getBlockPos().distSqr(origin)));return result;}
 public boolean transferEssence(String aspect,boolean insert,boolean simulate){return transferEssence(aspect,insert,simulate,null);}
 private boolean transferEssence(String aspect,boolean insert,boolean simulate,EssentiaTransport excluded){if(!essence()||!supported())return false;var options=new ArrayList<>(jars());if(insert)options.sort(Comparator.comparingInt((AlchemyMachine jar)->jar.total()==0?1:0));for(var jar:options)if(!jar.braced()&&jar!=excluded&&(insert?jar.insertEssence(aspect,1,simulate):jar.extractEssence(aspect,1,simulate))){if(!simulate){addInstability(1);particles();}return true;}return false;}
 public boolean extractFor(String aspect,Direction face,EssentiaTransport receiver,boolean simulate){return transferEssence(aspect,false,simulate,receiver);}
 public boolean connects(Direction face){return essence()&&supported();}public boolean canInput(Direction face){return connects(face);}public boolean canOutput(Direction face){return connects(face);}public Map<String,Integer> contents(Direction face){var values=new TreeMap<String,Integer>();for(var jar:jars())jar.snapshot().aspects().forEach((a,n)->values.merge(a,n,Integer::sum));return Map.copyOf(values);}public String suctionType(Direction face){return "";}public int suction(Direction face){return essence()&&supported()&&peer()!=null?16:0;}public int minimumSuction(){return 0;}public boolean insert(String aspect,Direction face,boolean simulate){return transferEssence(aspect,true,simulate);}public boolean extract(String aspect,Direction face,boolean simulate){return transferEssence(aspect,false,simulate);}
}
